-- Addendum 167: fill every Dubai school from KHDA's school data (Nov 2026)
-- Source: KHDA Dubai Private Schools Open Data (updated November 2025, fees 2024-25),
-- https://web.khda.gov.ae/en/Resources/KHDA-data-statistics
--
-- Run once. For every one of our Dubai schools that is on KHDA's list it:
--   * records which KHDA school it is (schools.khda_name, shown on the KHDA tab)
--   * sets the KHDA rating from KHDA
--   * fills area, curriculum, year groups, fees, phone and website ONLY where ours is empty,
--     so nothing a consultant typed is changed
-- Schools outside Dubai are left alone. Safe to run again: it only fills what is still empty.
-- The last result lists every Dubai school and what KHDA matched it to (unmatched first).

alter table public.schools
  add column if not exists khda_name text,
  add column if not exists khda_rating text,
  add column if not exists khda_inspection_year text,
  add column if not exists khda_report_url text;

comment on column public.schools.khda_name is
  'The school''s name on KHDA''s list, set by addendum 167. Shown on the KHDA tab.';

drop table if exists pg_temp.khda;
create temp table khda (
  name text primary key, key text, area text, curriculum text, lowest text, highest text,
  rating text, phone text, website text, fee_from numeric, fee_to numeric
);


drop table if exists pg_temp.khda_alias;
create temp table khda_alias (our_name text primary key, khda_name text);

-- The same name clean-up the site uses: lower case, no punctuation, no words like LLC or School.
create or replace function pg_temp.khda_key(n text) returns text language sql immutable as $$
  select coalesce(string_agg(w, ' ' order by i), '')
  from regexp_split_to_table(
         regexp_replace(replace(lower(coalesce(n, '')), '&', ' and '), '[^a-z0-9 ]+', ' ', 'g'), '\s+'
       ) with ordinality as t(w, i)
  where w <> '' and w <> all (array['llc', 'l', 'c', 'fze', 'fz', 'private', 'school', 'the', 'dubai', 'branch', 'pvt', 'ltd', 'co', 'est', 'dmcc', 'of'])
$$;

-- One KHDA school per school of ours: a hand-checked name first, then the cleaned-up name
-- (only when exactly one KHDA school has it).
drop table if exists pg_temp.khda_match;
create temp table khda_match as
select s.id, k.*
from public.schools s
join khda k on k.name = coalesce(
  s.khda_name,
  (select a.khda_name from khda_alias a where a.our_name = lower(trim(s.name))),
  (select k2.name from khda k2 where k2.key = pg_temp.khda_key(s.name)
     and (select count(*) from khda k3 where k3.key = k2.key) = 1)
)
where s.emirate is null or s.emirate = 'Dubai';

update public.schools s set
  khda_name          = m.name,
  khda_rating        = coalesce(m.rating, s.khda_rating),
  khda_report_url    = case when m.rating is not null and coalesce(s.khda_report_url, '') !~* '^https?://'
                            then 'https://web.khda.gov.ae/en/Resources/KHDA-data-statistics' else s.khda_report_url end,
  emirate            = coalesce(nullif(s.emirate, ''), 'Dubai'),
  area               = coalesce(nullif(s.area, ''), m.area),
  curriculum         = coalesce(nullif(s.curriculum, ''), m.curriculum),
  lowest_year_group  = case when s.lowest_year_group is null and s.highest_year_group is null then m.lowest else s.lowest_year_group end,
  highest_year_group = case when s.lowest_year_group is null and s.highest_year_group is null then m.highest else s.highest_year_group end,
  tuition_from       = coalesce(s.tuition_from, m.fee_from),
  tuition_to         = case when s.tuition_from is null then m.fee_to else s.tuition_to end,
  general_phone      = coalesce(nullif(s.general_phone, ''), m.phone),
  website_url        = coalesce(nullif(s.website_url, ''), m.website)
from khda_match m
where m.id = s.id;

notify pgrst, 'reload schema';

select s.name as our_school,
       coalesce(s.khda_name, 'Not on KHDA''s list') as khda_school,
       s.khda_rating, s.curriculum, s.lowest_year_group, s.highest_year_group, s.tuition_from, s.tuition_to
from public.schools s
where s.emirate is null or s.emirate = 'Dubai'
order by (s.khda_name is null) desc, s.name;
